import {supabase,currentUser} from './auth-client.mjs';import {safeAvatar,sortRoutes} from './trade-model.mjs';
const $=id=>document.getElementById(id),el=(t,s,c)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;if(c)n.className=c;return n;};let data,user,page=0,revision=0,routes=[];const size=20;
const cardName=n=>{const c=data.cards.find(c=>c.number===n);return '#'+n+(c?.gold?'G':'');};
function status(s){$('trade-status').textContent=s;}
function cardChip(n){const c=data.cards.find(c=>c.number===n),chip=el('span',cardName(n),'trade-card-chip');chip.title=c?c.name+' · '+c.stars+' stars':'';return chip;}
async function connect(id,give,receive,name){$('connect-title').textContent=name;$('connect-body').replaceChildren();$('connect-status').textContent='Checking swap availability…';$('connect-dialog').showModal();try{const actor=await currentUser();if(!actor)throw Error('Please log in again.');const {data:contact,error}=await supabase.rpc('trade_contacts',{p_season:data.season,p_partner:id,p_give:give,p_receive:receive});if(error)throw error;if((await currentUser())?.id!==actor.id)throw Error('Your account changed. Please retry.');$('connect-body').append(el('p','You give '+cardName(give)+' → receive '+cardName(receive),'swap-summary'));let shared=false;for(const [label,key] of [['In-Game ID','game_id'],['Discord Username','discord_username']])if(contact?.[key]){shared=true;const row=el('div',undefined,'contact-row'),copy=el('button','Copy');copy.onclick=async()=>{try{await navigator.clipboard.writeText(contact[key]);$('connect-status').textContent=label+' copied.';}catch{$('connect-status').textContent='Could not copy.';}};row.append(el('strong',label),el('span',contact[key]),copy);$('connect-body').append(row);}$('connect-status').textContent=shared?'Contact this player to arrange the in-game trade.':'This player has not revealed contact details.';}catch(e){$('connect-status').textContent=e.message;}}
function showTrader(row){const block=el('article',undefined,'trader-row'),player=el('div',undefined,'trader-player'),avatar=safeAvatar(row.avatar);if(avatar){const image=el('img');image.src=avatar;image.alt='';image.referrerPolicy='no-referrer';player.append(image);}else player.append(el('span','👤','avatar-placeholder'));const text=el('div');text.append(el('strong',row.name),el('time',new Date(row.updated_at).toLocaleString()));player.append(text);const cards=el('div',undefined,'trader-cards');cards.append(...row.ft.map(cardChip));const button=el('button','Connect');button.disabled=!user||!row.swaps.length;button.title=!user?'Log in to match your collection':!row.swaps.length?'No compatible swap with your current cards':'View available swaps';button.onclick=()=>{if(row.swaps.length===1){const s=row.swaps[0];connect(row.id,s.give,s.receive,row.name);}else{$('connect-title').textContent=row.name;$('connect-status').textContent='Choose a swap.';$('connect-body').replaceChildren(...row.swaps.slice(0,20).map(s=>{const choice=el('button','Give '+cardName(s.give)+' → receive '+cardName(s.receive),'swap-choice');choice.onclick=()=>{$('connect-dialog').close();connect(row.id,s.give,s.receive,row.name);};return choice;}));$('connect-dialog').showModal();}};block.append(player,cards,button);return block;}
async function load(){if(!data)return;const token=++revision;status('Finding traders…');try{user=await currentUser();const {data:rows,error}=await supabase.rpc('trade_listings',{p_season:data.season,p_set:Number($('trade-set').value)||null,p_star:Number($('trade-stars').value)||null,p_limit:size,p_offset:page*size});if(token!==revision)return;if(error)throw error;$('trader-list').replaceChildren(...rows.map(showTrader));status(rows.length?'':page?'No more listings.':'No available listings yet. Enable trading visibility in Account to join.');$('previous-page').disabled=page===0;$('next-page').disabled=rows.length<size;$('page-label').textContent='Page '+(page+1);}catch(e){$('trader-list').replaceChildren();status(e.code==='PGRST202'?'Trade Matching setup is not finished yet. Please check back soon.':'Could not load traders. Please try again.');}}
function renderRoutes(){$('routes').replaceChildren(...sortRoutes(routes,$('route-sort').value).map((route,index)=>{const box=el('article',undefined,'trade-route');box.append(el('h2','Route '+(index+1)+' · '+route.length+' trade'+(route.length>1?'s':'')));for(const [i,step] of route.steps.entries()){const row=el('div',undefined,'route-step');row.append(el('span',(i+1)+'. '+step.name),el('strong',cardName(step.give)+' → '+cardName(step.receive)));if(i===0){const button=el('button','Connect');button.onclick=()=>connect(step.id,step.give,step.receive,step.name);row.append(button);}box.append(row);}box.append(el('p','Update your inventory after each trade. Later steps must be rechecked.'));return box;}));}
$('find-route').onclick=async()=>{if(!await currentUser()){status('Log in to find routes using your cards.');return;}const n=Number($('route-card').value);if(!Number.isInteger(n)||n<1||n>135){status('Enter a card number from 1 to 135.');return;}$('find-route').disabled=true;status('Finding possible routes…');try{const {data:found,error}=await supabase.rpc('find_trade_routes',{p_season:data.season,p_target:n});if(error)throw error;routes=found;renderRoutes();status(found.length?'Possible routes are suggestions; inventory may change.':'No compatible route found within three trades.');}catch(e){status(e.message);}finally{$('find-route').disabled=false;}};
$('route-sort').onchange=renderRoutes;$('close-connect').onclick=()=>$('connect-dialog').close();$('refresh-listings').onclick=load;for(const id of ['trade-set','trade-stars'])$(id).onchange=()=>{page=0;load();};$('previous-page').onclick=()=>{page=Math.max(0,page-1);load();};$('next-page').onclick=()=>{page++;load();};supabase.auth.onAuthStateChange((_event,session)=>{if(!session){$('connect-dialog').close();$('connect-body').replaceChildren();routes=[];renderRoutes();}setTimeout(load,0);});
try{const r=await fetch(new URL('./album-data/autumn-tales.json',import.meta.url));if(!r.ok)throw Error('Album catalog unavailable');data=await r.json();for(const s of data.sets)$('trade-set').append(new Option(s.number+'. '+s.name,s.number));await load();}catch(e){status(e.message);}
